_JIANNIAN = (
    "走在廟埕抬頭，屋脊上總有一條彩色的帶子。"
    "龍、鳳、牡丹，還有一整排小人物，"
    "一片一片黏在屋頂上，太陽一照就閃得很亮。\n"
    "\n"
    "這就是剪黏。"
    "剪黏的材料不是石頭，是磁磚、玻璃和瓷碗的碎片。"
    "這些東西早年不容易取得，廟宇用量卻很大，"
    "剩下的碎片就挑顏色、挑厚薄，再一片片剪成需要的形狀。\n"
    "\n"
    "挑的時候先看顏色，紅的配藍的、藍的配綠的，全憑師傅的眼睛。"
    "除了屋脊，廟門上方和戲台的簷口也常有剪黏的圖案。\n"
    "\n"
    "師傅的做法很像拼圖。先在紙上畫好圖，俗稱畫「本」，"
    "再照著本子，把碎片一片片剪、一片片黏到坯上。"
    "一條屋脊做完，常常要花上好幾個月。\n"
    "\n"
    "老師傅常說，剪黏好看有個原因：碎片是燒出來的，還上過釉，"
    "光滑又不怕日曬雨淋，幾十年下來顏色還在。"
    "屋脊除了漂亮，也能讓雨水不容易從瓦縫灌進去。\n"
    "\n"
    "可惜會剪的人越來越少。學藝要從剪碎片開始，"
    "手不穩，碎片就在手上碎了。於是有人把剪黏搬進教室，"
    "讓孩子用安全剪和壓克力片，先學會耐心。"
)


